<?php
require_once __DIR__.'/config/auth.php';
$code=strtoupper(trim((string)($_GET['kode']??$_POST['kode']??'')));$error='';$reviewSent=false;
$st=$pdo->prepare('SELECT o.*,t.nomor_meja FROM orders o LEFT JOIN `tables` t ON t.id=o.table_id WHERE o.kode_pesanan=?');$st->execute([$code]);$order=$st->fetch();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['rating'])){
 csrf_check();if(!$order)$error='pesanan tidak ditemukan.';elseif($order['status_pesanan']!=='Selesai')$error='ulasan baru bisa dikirim setelah pesanan selesai.';else{$name=clean_text((string)($_POST['nama']??''),100);$rating=max(1,min(5,(int)($_POST['rating']??5)));$comment=clean_text((string)($_POST['komentar']??''),1000);if($name==='')$error='nama wajib diisi.';else{try{$ins=$pdo->prepare('INSERT INTO reviews (order_id,nama,rating,komentar,status) VALUES (?,?,?,?,\'pending\')');$ins->execute([(int)$order['id'],$name,$rating,$comment]);header('Location: '.BASE_URL.'/track.php?kode='.urlencode($code).'&review=1');exit;}catch(PDOException $e){$error='ulasan untuk pesanan ini sudah pernah dikirim.';}}}}
$pageTitle='Lacak Pesanan';require __DIR__.'/includes/header.php'; ?>
<section class="max-w-3xl mx-auto px-4 py-10"><p class="section-kicker">kami siapkan dengan hati</p><h1 class="font-serif text-4xl mt-2">lacak pesanan</h1><form method="get" class="card p-4 mt-6 flex flex-col sm:flex-row gap-3"><input class="field flex-1 uppercase" name="kode" value="<?= h($code) ?>" placeholder="masukkan kode pesanan, mis. CFY261026ABC123" required><button class="btn btn-coffee">Lacak</button></form>
<?php if(isset($_GET['baru'])):?><div class="flash flash-ok">pesanan kamu berhasil dibuat! simpan kode pesanan untuk mengecek status.</div><?php endif;?><?php if($error):?><div class="flash flash-error"><?= h($error) ?></div><?php endif;?><?php if(isset($_GET['review'])):?><div class="flash flash-ok">terima kasih! ulasan kamu sudah dikirim dan menunggu moderasi.</div><?php endif;?>
<?php if($order):?><div class="card p-5 sm:p-8 mt-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs text-coffee/55">kode pesanan</p><h2 class="font-bold text-2xl mt-1"><?= h($order['kode_pesanan']) ?></h2><p class="text-sm text-coffee/60 mt-1">atas nama <?= h($order['nama_pelanggan']) ?> · <?= $order['nomor_meja']?'Meja '.h($order['nomor_meja']):'Take away' ?></p></div><div class="text-right"><p class="text-xs text-coffee/55">total tagihan</p><p class="font-bold text-xl mt-1"><?= money($order['total']) ?></p><span class="status-pill" id="payment-status"><?= h($order['status_bayar']) ?></span></div></div><div class="my-7 border-t border-coffee/10"></div><p class="section-kicker">status pesanan</p><div class="grid grid-cols-4 gap-2 mt-4" id="status-steps"><?php $steps=['Diterima','Diproses','Siap','Selesai'];$idx=array_search($order['status_pesanan'],$steps,true);foreach($steps as $i=>$s):?><div class="text-center"><div class="rounded-full w-10 h-10 mx-auto flex items-center justify-center <?= $idx!==false&&$i<=$idx?'bg-sage text-white':'bg-coffee/10 text-coffee/40' ?>"><?= $i+1 ?></div><p class="text-[10px] sm:text-xs mt-2 <?= $idx!==false&&$i<=$idx?'font-semibold':'text-coffee/45' ?>"><?= h($s) ?></p></div><?php endforeach;?></div><p class="text-sm text-coffee/60 mt-5" id="status-message"><?= $order['status_pesanan']==='Selesai'?'pesanan selesai. terima kasih sudah mampir ke Kopiah!':'status diperbarui otomatis setiap 5 detik.' ?></p><p class="text-xs text-coffee/50 mt-2">dibuat pada <?= h(date('d M Y H:i',strtotime($order['created_at']))) ?> WIB</p>
<?php if($order['status_pesanan']==='Selesai'): $rv=$pdo->prepare('SELECT id FROM reviews WHERE order_id=?');$rv->execute([(int)$order['id']]);$already=(bool)$rv->fetchColumn();if(!$already&&!$reviewSent):?><div class="border-t border-coffee/10 mt-6 pt-6"><h3 class="font-serif text-2xl">ceritakan pengalamanmu</h3><p class="text-sm text-coffee/60 mt-2">ulasan kamu membantu kami jadi lebih baik.</p><form method="post" class="mt-4 space-y-4"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="kode" value="<?= h($code) ?>"><div><label class="field-label">nama</label><input class="field" name="nama" required maxlength="100" value="<?= h($order['nama_pelanggan']) ?>"></div><div><label class="field-label">rating</label><select class="field" name="rating"><option value="5">★★★★★ — mantap banget</option><option value="4">★★★★☆ — puas</option><option value="3">★★★☆☆ — cukup</option><option value="2">★★☆☆☆ — kurang</option><option value="1">★☆☆☆☆ — perlu perbaikan</option></select></div><div><label class="field-label">komentar</label><textarea class="field" name="komentar" rows="3" maxlength="1000" placeholder="apa yang paling kamu suka?"></textarea></div><button class="btn btn-coffee">Kirim ulasan</button></form></div><?php elseif($already):?><p class="text-sm mt-5 text-sage font-semibold">ulasan untuk pesanan ini sudah tercatat.</p><?php endif; endif;?></div><script>const trackCode=<?= json_encode($code) ?>;const initialOrderStatus=<?= json_encode($order['status_pesanan']) ?>;async function refreshOrder(){try{const r=await fetch('<?= h(BASE_URL) ?>/api/order-status.php?kode='+encodeURIComponent(trackCode),{cache:'no-store'});const d=await r.json();if(d.ok){document.getElementById('payment-status').textContent=d.order.status_bayar;const steps=['Diterima','Diproses','Siap','Selesai'];const i=steps.indexOf(d.order.status_pesanan);document.querySelectorAll('#status-steps>div').forEach((el,n)=>{const circ=el.firstElementChild,lab=el.lastElementChild;circ.className='rounded-full w-10 h-10 mx-auto flex items-center justify-center '+(i>=n?'bg-sage text-white':'bg-coffee/10 text-coffee/40');lab.className='text-[10px] sm:text-xs mt-2 '+(i>=n?'font-semibold':'text-coffee/45')});document.getElementById('status-message').textContent=d.order.status_pesanan==='Selesai'?'pesanan selesai. terima kasih sudah mampir ke Kopiah!':'status diperbarui otomatis setiap 5 detik.';if(initialOrderStatus!=='Selesai'&&d.order.status_pesanan==='Selesai'){location.reload()}}}catch(e){}}setInterval(refreshOrder,5000);</script><?php elseif($code!==''):?><div class="flash flash-warn mt-6">kode pesanan belum ditemukan. pastikan kode yang dimasukkan benar.</div><?php endif;?></section>
<?php require __DIR__.'/includes/footer.php'; ?>
